package ec.edu.ucacue.odontocare.reporting;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.time.LocalDate;import java.util.*;import org.junit.jupiter.api.Test;import com.lowagie.text.pdf.PdfReader;import com.lowagie.text.pdf.parser.PdfTextExtractor;import ec.edu.ucacue.odontocare.auth.infrastructure.UserAccountRepository;import ec.edu.ucacue.odontocare.clinicalrecord.application.ConsultationService;import ec.edu.ucacue.odontocare.clinicalrecord.domain.ClinicalRecord;import ec.edu.ucacue.odontocare.clinicalrecord.infrastructure.*;import ec.edu.ucacue.odontocare.odontogram.application.OdontogramService;import ec.edu.ucacue.odontocare.patient.domain.Patient;import ec.edu.ucacue.odontocare.patient.infrastructure.ClinicalBackgroundRepository;import ec.edu.ucacue.odontocare.treatment.application.TreatmentService;
class ClinicalPdfServiceTests{
 @Test void generatesConsolidatedPdfWithPatientIdentity()throws Exception{
  var records=mock(ClinicalRecordRepository.class);var backgrounds=mock(ClinicalBackgroundRepository.class);var consultationRepo=mock(DentalConsultationRepository.class);var consultations=mock(ConsultationService.class);var odontogram=mock(OdontogramService.class);var treatment=mock(TreatmentService.class);var users=mock(UserAccountRepository.class);var record=mock(ClinicalRecord.class);var patient=mock(Patient.class);
  when(record.getPatient()).thenReturn(patient);when(patient.getId()).thenReturn(14L);when(patient.getClinicalRecordNumber()).thenReturn("DEMO-HC-001");when(patient.getFirstNames()).thenReturn("ANA");when(patient.getLastNames()).thenReturn("DEMOSTRATIVA");when(patient.getIdentification()).thenReturn("DEMO-ID");when(patient.getBirthDate()).thenReturn(LocalDate.of(1990,1,15));when(patient.getSex()).thenReturn("PRUEBA");when(patient.getPhone()).thenReturn("000");when(patient.getEmail()).thenReturn("demo@example.test");when(patient.getAddress()).thenReturn("DIRECCION PRUEBA");when(records.findById(11L)).thenReturn(Optional.of(record));when(backgrounds.findByPatientIdAndActiveTrue(14L)).thenReturn(List.of());when(consultationRepo.findByClinicalRecordIdOrderByConsultationDateDescIdDesc(11L)).thenReturn(List.of());when(odontogram.current(11L)).thenReturn(List.of());when(treatment.procedures(11L)).thenReturn(List.of());when(treatment.plans(11L)).thenReturn(List.of());when(treatment.evolutions(11L)).thenReturn(List.of());
  var service=new ClinicalPdfService(records,backgrounds,consultationRepo,consultations,odontogram,treatment,users,mock(ec.edu.ucacue.odontocare.odontogram.infrastructure.DentalPieceRepository.class),"Institución de prueba","OdontoUcacue");byte[] bytes=service.generate(11L,null);assertTrue(bytes.length>1000);PdfReader reader=new PdfReader(bytes);String text=new PdfTextExtractor(reader).getTextFromPage(1);assertTrue(text.contains("OdontoUcacue"));assertTrue(text.contains("DEMO-HC-001"));assertTrue(text.contains("ANA DEMOSTRATIVA"));
 }
}
